/**
 * fix-exhaustive-deps-v3.mjs
 *
 * Fixes react-hooks/exhaustive-deps warnings by:
 * 1. Reading ESLint JSON output to know exactly what to add/remove
 * 2. Finding the dep array (including multi-line ones) and modifying it
 * 3. Adding missing deps or removing unnecessary deps
 *
 * Usage: node scripts/fix-exhaustive-deps-v3.mjs
 * Requires: eslint_exhaustive.json (generated by npx eslint . --format json)
 */

import fs from 'fs';
import path from 'path';

const reportPath = process.argv[2] || 'eslint_current.json';
const report = JSON.parse(fs.readFileSync(reportPath, 'utf8'));

// Collect warnings by file
const fileWarnings = new Map();
for (const result of report) {
  for (const msg of result.messages || []) {
    if (msg.ruleId !== 'react-hooks/exhaustive-deps') continue;
    const fp = result.filePath;
    if (!fileWarnings.has(fp)) fileWarnings.set(fp, []);
    fileWarnings.get(fp).push({
      line: msg.line,
      column: msg.column,
      message: msg.message,
    });
  }
}

let totalFixed = 0;
let totalFiles = 0;

for (const [filePath, warnings] of fileWarnings) {
  let content = fs.readFileSync(filePath, 'utf8');
  const originalContent = content;

  // Process warnings sorted by line (bottom-up)
  const sorted = [...warnings].sort((a, b) => b.line - a.line);

  for (const warn of sorted) {
    const { line: warnLine, message } = warn;

    // Find the dep array [ ... ] after the hook call
    const lines = content.split('\n');
    let startLineIdx = warnLine - 1;

    let arrayStart = -1;
    let arrayEnd = -1;

    // Try single-line dep array: look for ] on the same line after [
    for (let i = startLineIdx; i < lines.length && i < startLineIdx + 3; i++) {
      const line = lines[i];
      // Search for [ that looks like a dep array start (preceded by ,)
      const bracketIdx = line.indexOf('[');
      if (bracketIdx >= 0) {
        const before = line.substring(0, bracketIdx).trim();
        if (before.endsWith(',') || before.endsWith('(') || before.endsWith('=>') || before.endsWith(')')) {
          const after = line.substring(bracketIdx + 1);
          const closeIdx = after.indexOf(']');
          if (closeIdx >= 0) {
            const inner = after.substring(0, closeIdx);
            if (inner.length < 600 && !inner.includes('{') && inner.split(',').length <= 20) {
              arrayStart = i;
              arrayEnd = i;
              break;
            }
          }
        }
      }
    }

    // Try multi-line: look for a line ending with ,[
    if (arrayStart < 0) {
      for (let i = startLineIdx; i < lines.length && i < startLineIdx + 25; i++) {
        const trimmed = lines[i].trimEnd();
        // Line ending with ,  or just standalone [
        if (trimmed.endsWith(',[') || trimmed.endsWith(', [')) {
          arrayStart = i;
          // Find matching ] within next 20 lines
          for (let j = i; j < lines.length && j < i + 20; j++) {
            const closeIdx = lines[j].indexOf(']');
            if (closeIdx >= 0) {
              arrayEnd = j;
              break;
            }
          }
          if (arrayEnd >= 0) break;
        }
      }
    }

    // Try another approach: a line that's just [
    if (arrayStart < 0) {
      for (let i = startLineIdx; i < lines.length && i < startLineIdx + 25; i++) {
        const trimmed = lines[i].trim();
        if (trimmed === '[' || trimmed === '[' || trimmed === ', [') {
          arrayStart = i;
          let depth = 1;
          for (let j = i + 1; j < lines.length && depth > 0; j++) {
            for (let k = 0; k < lines[j].length; k++) {
              if (lines[j][k] === '[') depth++;
              if (lines[j][k] === ']') {
                depth--;
                if (depth === 0) {
                  arrayEnd = j;
                  break;
                }
              }
            }
            if (arrayEnd >= 0) break;
          }
          if (arrayEnd >= 0) break;
        }
      }
    }

    if (arrayStart < 0 || arrayEnd < 0) {
      console.log(`  ⚠️ Could not find dep array in ${path.basename(filePath)} near line ${warnLine}`);
      continue;
    }

    // Extract the full dep array content
    const arrayLines = lines.slice(arrayStart, arrayEnd + 1);
    const fullArrayStr = arrayLines.join('\n');

    // Parse deps from the array
    // Extract everything between [ and ]
    const startBracket = fullArrayStr.indexOf('[');
    const endBracket = fullArrayStr.lastIndexOf(']');
    if (startBracket < 0 || endBracket < 0) continue;

    const rawContent = fullArrayStr.substring(startBracket + 1, endBracket);
    // Split by comma, clean up newlines and whitespace
    const deps = rawContent
      .split(',')
      .map(d => d.replace(/\/\/.*$/, '').replace(/\n/g, '').trim())
      .filter(d => d.length > 0);

    // Parse the warning message
    const isUnnecessary = message.includes('unnecessary dependency');
    const isMissing = message.includes('missing dependenc');

    let modified = false;

    if (isUnnecessary) {
      const unnecMatches = [...message.matchAll(/'([^']+)'/g)];
      for (const match of unnecMatches) {
        const unnecDep = match[1];
        const filtered = deps.filter(d => d !== unnecDep);
        if (filtered.length !== deps.length) {
          // Reconstruct array preserving formatting
          const newFull = reconstructArray(filtered);
          content = replaceInContent(content, arrayLines, newFull);
          modified = true;
          totalFixed++;
          console.log(`  ✅ REMOVED '${unnecDep}' in ${path.basename(filePath)}:${warnLine}`);
        }
      }
    } else if (isMissing) {
      const missingMatches = [...message.matchAll(/'([^']+)'/g)];
      const missingDeps = missingMatches.map(m => m[1]);

      const existingSet = new Set(deps);
      const toAdd = missingDeps.filter(d => !existingSet.has(d));

      if (toAdd.length > 0) {
        const allDeps = [...deps, ...toAdd];
        const newFull = reconstructArray(allDeps);
        content = replaceInContent(content, arrayLines, newFull);
        modified = true;
        totalFixed++;
        console.log(`  ✅ ADDED [${toAdd.join(', ')}] in ${path.basename(filePath)}:${warnLine}`);
      }
    }
  }

  if (content !== originalContent) {
    fs.writeFileSync(filePath, content, 'utf8');
    totalFiles++;
  }
}

function reconstructArray(deps) {
  if (deps.length === 0) return '[]';
  // Format as multi-line: [\n  dep1,\n  dep2,\n]
  return '[\n' + deps.map(d => '  ' + d).join(',\n') + ',\n]';
}

function replaceInContent(content, oldArrayLines, newArrayStr) {
  const oldFull = oldArrayLines.join('\n');
  const idx = content.indexOf(oldFull);
  if (idx >= 0) {
    return content.substring(0, idx) + newArrayStr + content.substring(idx + oldFull.length);
  }
  return content;
}

console.log(`\n✅ Fixed ${totalFixed} exhaustive-deps warnings across ${totalFiles} files`);
